def solve(I):
    H,W=len(I),len(I[0])
    ones=[(r,c) for r in range(H) for c in range(W) if I[r][c]==1]
    # lines: row-line from horizontal pairs, col-line from vertical pairs
    rowsL=sorted({a[0] for a,b in zip(ones,ones[1:]) if True}) or None
    # proper: collect candidate lines from all pairs sharing row or col
    cands=set()
    for a,b in [(ones[i],ones[j]) for i in range(len(ones)) for j in range(i+1,len(ones))]:
        if a[0]==b[0]: cands.add(('row',a[0]))
        if a[1]==b[1]: cands.add(('col',a[1]))
    out=[[1]*W for _ in range(H)]  # placeholder
    O=[row[:] for row in I]
    for typ,val in cands:
        for r in range(H): O[r][val]=1
        for c in range(W): O[val][c]=1
    # recolor: blocks whose cells lie on any line cell
    on={(rr,cc) for rr in range(H) for cc in range(W) if O[rr][cc]==1 and I[rr][cc]==0}
    for r in range(H):
        for c in range(W):
            if I[r][c]==2 and (r,c) in on: O[r][c]=1
    return O
